## Check 14: spelling, wrong names and over-wide lines in added prose

BASE for this check (the common-setup `merge-base HEAD origin/main` is wrong for a PR on another base branch): open PR, `BASE=$(git -C WT merge-base HEAD origin/$(gh api repos/positron-ai/tron/pulls/N --jq .base.ref))`; merged PR, `BASE=$(gh api repos/positron-ai/tron/pulls/N --jq .base.sha)`, which equals the first parent of the merge commit (`git -C WT log --merges --oneline --grep='#N'`). Merge-base against the base branch after it merged the PR returns HEAD (PR 2011 on hwattention_sync: empty diff); merge-base against main returns the whole branch (9108 diff lines, 47 files).

1. Added prose lines with HEAD line numbers: comment text, string-literal contents (kind S), and .md lines outside fences (kind M). Fence parity comes from the full file at HEAD, not from the hunk.
```
git -C WT diff BASE HEAD > pr.diff
cat > prose.py <<'EOF'
import re, sys, subprocess
WT, HEAD, D = sys.argv[1:4]
f=None; n=0; fence=set()
def ok(f): return f and (f.endswith('.md') or re.match(r'(h|src|t|doc)/', f) and f.endswith(('.hpp','.cpp','.h','.c','.inl')))
def fenced_lines(f):
    txt=subprocess.run(['git','-C',WT,'show',f'{HEAD}:{f}'],capture_output=True,text=True).stdout.split('\n')
    s=set(); inside=False
    for i,l in enumerate(txt,1):
        if l.lstrip().startswith('```'): inside=not inside; s.add(i)
        elif inside: s.add(i)
    return s
for raw in open(D, encoding='utf-8', errors='replace'):
    l=raw.rstrip('\n')
    if l.startswith('+++ '):
        f=l[4:]; f=f[2:] if f.startswith('b/') else f; n=0
        fence=fenced_lines(f) if f.endswith('.md') else set(); continue
    m=re.match(r'^@@ -\d+(?:,\d+)? \+(\d+)', l)
    if m: n=int(m.group(1)); continue
    if l.startswith('-') or l.startswith('\\'): continue
    if l.startswith('+') and ok(f):
        b=l[1:]
        if f.endswith('.md'):
            if n not in fence: print(f'{f}:{n}\tM\t{b}')
        else:
            cm=re.search(r'(//|/\*|^\s*\*\s)(.*)', b); st=re.findall(r'"((?:[^"\\]|\\.)*)"', b)
            if cm: print(f'{f}:{n}\tC\t{cm.group(2)}')
            elif st: print(f'{f}:{n}\tS\t{" ".join(st)}')
    n+=1
EOF
python3 -I prose.py WT HEAD pr.diff > prose.txt
```
2. Allow list from three sources, lower-cased and split at underscores: every word at BASE in h/ src/ t/ (comment and string words included, so it also holds main's typos, which step 4 recovers); identifiers on code lines at HEAD in the C++ files the diff touches (the PR's own new identifiers are vocabulary, its typos are not); file basenames at HEAD.
```
{ git -C WT grep -ohE '[A-Za-z_][A-Za-z0-9_]{2,}' BASE -- h src t
  for f in $(grep '^+++ b/' pr.diff | sed 's#^+++ b/##' | grep -E '^(h|src|t)/.*\.(hpp|cpp|h|c|inl)$'); do git -C WT show HEAD:$f | sed -E 's#//.*$##; s#"([^"\\]|\\.)*"##g' | grep -v -E '^\s*(\*|/\*)' | grep -oE '[A-Za-z_][A-Za-z0-9_]{2,}'; done
  git -C WT ls-tree -r --name-only HEAD | sed 's#.*/##; s#\..*$##'
} | tr 'A-Z' 'a-z' | tr '_' '\n' | grep -E '^[a-z]{3,}$' | sort -u > lexicon.txt
```
3. Dictionary spell check (pyspellchecker through uv; cached after the first run, network needed only then; if the import fails, `uvx codespell prose.txt` is the fallback: it finds regiser, desriptor, anomoly but no run-together word, so write Insufficient data for those). A word whose only capital is its first letter is kept and lower-cased (Thsi). Tokens with a digit, an underscore or an inner capital, and backticked spans, are removed. Output: BAD (one line per hit), VOCAB (a hit on two or more added lines of this PR: author vocabulary, read once; none of the 22 known Wade typos recurs), EXCUSED (unknown to the dictionary but allowed: input to step 4).
```
cat > spell.py <<'EOF'
import re, sys
from spellchecker import SpellChecker
sp=SpellChecker(); allow=set(w.strip() for w in open(sys.argv[2]))
seen={}; hits=[]
def resolves(w):
    for p in ('un','de','re','non','sub','pre'):
        if w.startswith(p) and len(w)>len(p)+2 and sp.known([w[len(p):]]): return True
    for s in ('s','es','ed','ize','ized','ation','ization'):
        if w.endswith(s) and len(w)>len(s)+2 and sp.known([w[:-len(s)]]): return True
    return False
def prefix_of_code(w):
    return len(w)>=4 and any(a.startswith(w) and len(a)>len(w) for a in allow)
for line in open(sys.argv[1], encoding='utf-8', errors='replace'):
    loc,_,rest=line.rstrip('\n').partition('\t'); kind,_,text=rest.partition('\t')
    t=re.sub(r'`[^`]*`',' ',text); t=re.sub(r'\b\w*[_0-9]\w*\b|\b\w+[A-Z]\w*\b',' ',t)
    words=[w.lower() for w in re.findall(r'\b[A-Za-z][a-z]{2,}\b',t)]
    for w in sp.unknown(words):
        if w in allow or (w.endswith('s') and w[:-1] in allow) or (w.endswith('es') and w[:-2] in allow): seen.setdefault(w,[]).append(loc)
        elif resolves(w): seen.setdefault('(affix)'+w,[]).append(loc)
        elif prefix_of_code(w): seen.setdefault('(prefix)'+w,[]).append(loc)
        else: hits.append((loc,w,sp.correction(w)))
from collections import Counter
cnt=Counter(w for _,w,c in set(hits))
for loc,w,c in hits:
    if cnt[w]>=2: print('VOCAB',loc,'|',w,f'(on {cnt[w]} added prose lines of this PR: author vocabulary, read once)')
    else: print('BAD',loc,'|',w,'->',c or '(no correction: run-together or shifted space? read it)')
for w,l in sorted(seen.items()): print('EXCUSED',w,len(l),l[0])
EOF
uv run -q --with pyspellchecker python -I spell.py prose.txt lexicon.txt > spell.txt; grep -E '^(BAD|VOCAB)' spell.txt
```
A BAD hit with a correction is a finding. A BAD hit with no correction is read: a run-together pair (specifiedlocation, aremultiple, someinternal) or a shifted space (launcha ctivities) is a finding; a compound of two nouns (kcache, tracepoint, cpulist) is a dictionary gap and is dropped. pyspellchecker lacks some real words (unmodeled, chokepoint, canonicalized, zeroize, dequantization); the affix rule removes most, and a surviving one-off compound is not a finding.

4. Allowed words that are only comment or string text: count code hits at HEAD with comments and quoted spans stripped (case-insensitive substring, trailing s dropped). Zero hits means the word reached the allow list through a comment or string at BASE: read it. A word with a dictionary correction is a typo already on main that the diff re-adds (eahc at PR 1722 hwattention.hpp:166, allowed through BASE device.hpp:78; comamnds at PR 1707; anomoly at PR 2011 driver.cpp:833, where the two BASE hits are spdlog strings). A real word (doneness, upstack, enqueuing, fixup) is dropped.
```
for w in $(grep EXCUSED spell.txt | grep -v '(affix)\|(prefix)' | awk '{print $2}'); do s=${w%s}; c=$(git -C WT grep -n -i -E "$s" HEAD -- h src t | sed -E 's#//.*$##; s#"([^"\\]|\\.)*"##g' | grep -v -E '^[^:]+:[0-9]+:\s*(\*|/\*)' | grep -i -c -E "$s"); [ "$c" -eq 0 ] && echo "read: $w"; done
```
5. Identifier-shaped tokens in comment and .md prose only (string literals are log labels; no Wade comment targets one). Skip an all-caps token with no underscore or digit whose lower-case form is a dictionary word (NEXT, WAS, CHECKING), a file basename (t_hwattention, shard_based_hw_attention_api), and any token whose case-insensitive whole-word count over the whole tree (token or token minus trailing s) is above 1. Report only when a HEAD identifier with two or more occurrences in h/ src/ t/ differs from the token by one missing, extra, substituted or transposed letter; the token plus or minus a suffix (shard_layer vs shard_layer_t) and the same name in another case convention (counter_track vs CounterTrack) are not letter edits. With no such neighbour there is no corrected line to suggest, so nothing is posted (align_down, xfer_wait, consumed_head_index, runtron_hw).
```
cat > step5.py <<'EOF'
import re, sys, subprocess
WT, HEAD, prose = sys.argv[1:4]
from spellchecker import SpellChecker
sp=SpellChecker()
def git(*a): return subprocess.run(['git','-C',WT,*a],capture_output=True,text=True).stdout
toks={}
for line in open(prose, encoding='utf-8', errors='replace'):
    loc,_,rest=line.rstrip('\n').partition('\t'); kind,_,text=rest.partition('\t')
    if kind not in 'CM': continue
    text=re.sub(r'`[^`]*`',' ',text)
    for t in re.findall(r'\b[A-Za-z]+(?:_[A-Za-z0-9]+)+\b|\b[A-Z]{2,}[A-Z0-9_]+\b', text): toks.setdefault(t,loc)
base=set(p.rsplit('/',1)[-1].split('.')[0].lower() for p in git('ls-tree','-r','--name-only',HEAD).splitlines())
ids={}
for w in git('grep','-ohE',r'\b[A-Za-z_][A-Za-z0-9_]{2,}\b',HEAD,'--','h','src','t').split():
    ids[w]=ids.get(w,0)+1
def lev(a,b):
    if abs(len(a)-len(b))>1: return 3
    prev=list(range(len(b)+1))
    for i,ca in enumerate(a,1):
        cur=[i]
        for j,cb in enumerate(b,1): cur.append(min(prev[j]+1,cur[j-1]+1,prev[j-1]+(ca!=cb)))
        prev=cur
    return prev[-1]
def transposed(a,b):
    if len(a)!=len(b): return False
    d=[i for i in range(len(a)) if a[i]!=b[i]]
    return len(d)==2 and d[1]==d[0]+1 and a[d[0]]==b[d[1]] and a[d[1]]==b[d[0]]
for t,loc in sorted(toks.items()):
    lc=t.lower()
    if '_' not in t and not re.search(r'\d',t) and sp.known([lc]): continue
    if lc in base: continue
    n=sum(int(x.rsplit(':',1)[1]) for x in git('grep','-c','-i','-w','-E',f'{t}|{t.rstrip("s")}',HEAD).splitlines())
    if n>1: continue
    nb=[]
    for w,c in ids.items():
        wl=w.lower()
        if c<2 or wl==lc or wl.replace('_','')==lc.replace('_',''): continue
        if wl.startswith(lc) or lc.startswith(wl): continue
        if lev(lc,wl)==1 or transposed(lc,wl): nb.append((w,c))
    print(('FIND' if nb else 'cand'), t, loc, 'hits=%d'%n, 'neighbour=%s'%nb)
EOF
uv run -q --with pyspellchecker python -I step5.py WT HEAD prose.txt | grep '^FIND'
```
6. Heading case per added or changed .md file: list headings at HEAD outside fences and report an added heading whose first-letter case differs from its siblings at the same level.
